import { useMemo, useState } from 'react';
import type React from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, useParams } from 'wouter';
import {
  ArrowRight, BarChart3, Bell, Bookmark, BookmarkCheck, CalendarDays, Check,
  ChevronRight, Clock3, Code2, ExternalLink,
  FileCode2, Filter, Github, Globe2, Heart, LayoutDashboard, Lightbulb,
  ListFilter, LogOut, Menu, Plus, Rocket, Search, ShieldCheck,
  Sparkles, Target, Trophy, Users, X, Zap,
} from 'lucide-react';
import {
  getGetAdminAnalyticsQueryKey, getGetAdminHackathonsQueryKey, getGetAdminUsersQueryKey,
  getGetCurrentUserQueryKey, getGetDashboardQueryKey, getGetHackathonQueryKey,
  getGetMyProjectsQueryKey, getGetMyRegistrationsQueryKey, getGetMyTeamsQueryKey,
  getGetOrganizerDashboardQueryKey, getGetProfileQueryKey, getGetRecommendationsQueryKey,
  useBookmarkHackathon, useCancelRegistration, useCreateHackathon,
  useCreateProject, useCreateTeam, useDeleteHackathon, useGetAdminAnalytics,
  useGetAdminHackathons, useGetAdminUsers, useGetCurrentUser, useGetDashboard,
  useGetHackathon, useGetMyProjects, useGetMyRegistrations, useGetMyTeams,
  useGetOrganizerDashboard, useGetProfile, useGetRecommendations, useInviteToTeam,
  useListHackathons, useLogin, useLogout, useRegister, useRegisterForHackathon,
  useSubmitProject, useUnbookmarkHackathon, useUpdateHackathon, useUpdateProfile,
  setAuthTokenGetter,
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
setAuthTokenGetter(() => localStorage.getItem('hacksphere_token'));
const cn = (...classes: Array<string | false | null | undefined>) => classes.filter(Boolean).join(' ');
const money = (value = 0) => `$${new Intl.NumberFormat('en-US').format(value)}`;
const date = (value?: string) => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(new Date(value)) : '—';
const dateTime = (value?: string) => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : '—';
const initials = (name = 'HS') => name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();

function Logo({ dark = false }: { dark?: boolean }) {
  return <Link href="/" className="flex items-center gap-2.5 group" data-testid="link-logo">
    <span className={cn('logo-mark', dark && 'logo-mark-dark')}><span>H</span></span>
    <span className={cn('font-display text-lg font-extrabold tracking-tight', dark ? 'text-cream' : 'text-ink')}>Hack<span className="text-yellow">Sphere</span></span>
  </Link>;
}

function Button({ children, variant = 'primary', className, type = 'button', onClick, disabled, testId = 'button-action' }: {
  children: React.ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'outline' | 'danger'; className?: string; type?: 'button' | 'submit'; onClick?: () => void; disabled?: boolean; testId?: string;
}) {
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId}
    className={cn('btn', `btn-${variant}`, className, disabled && 'opacity-50 cursor-not-allowed')}>{children}</button>;
}

function Badge({ children, tone = 'neutral' }: { children: React.ReactNode; tone?: 'neutral' | 'yellow' | 'teal' | 'red' | 'dark' }) {
  return <span className={cn('badge', `badge-${tone}`)}>{children}</span>;
}

function Skeleton({ className = '' }: { className?: string }) { return <div className={cn('skeleton', className)} />; }
function LoadingState() { return <div className="space-y-3" data-testid="state-loading">{[1, 2, 3].map((i) => <div key={i} className="panel p-5 flex gap-4"><Skeleton className="h-12 w-12 rounded-xl" /><div className="flex-1 space-y-2"><Skeleton className="h-4 w-2/5" /><Skeleton className="h-3 w-4/5" /></div></div>)}</div>; }
function ErrorState({ onRetry }: { onRetry?: () => void }) { return <div className="empty-state" data-testid="state-error"><div className="empty-icon"><X size={22} /></div><h3>Could not load this view</h3><p>Something got in the way. Try again in a moment.</p>{onRetry && <Button variant="outline" onClick={onRetry} testId="button-retry">Retry</Button>}</div>; }
function EmptyState({ icon: Icon = Rocket, title, text, action }: { icon?: typeof Rocket; title: string; text: string; action?: React.ReactNode }) { return <div className="empty-state" data-testid="state-empty"><div className="empty-icon"><Icon size={22} /></div><h3>{title}</h3><p>{text}</p>{action}</div>; }

function AppShell({ children, title, eyebrow }: { children: React.ReactNode; title?: string; eyebrow?: string }) {
  const [location, setLocation] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const { data: user } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  const logout = useLogout();
  const nav = [
    { href: '/dashboard', label: 'Overview', icon: LayoutDashboard },
    { href: '/hackathons', label: 'Discover', icon: Search },
    { href: '/recommendations', label: 'For you', icon: Sparkles },
    { href: '/registrations', label: 'Registrations', icon: CalendarDays },
    { href: '/teams', label: 'Teams', icon: Users },
    { href: '/projects', label: 'Projects', icon: FileCode2 },
  ];
  const isActive = (href: string) => href === '/hackathons' ? location.startsWith('/hackathons') : location.startsWith(href);
  const doLogout = () => logout.mutate(undefined, { onSuccess: () => { localStorage.removeItem('hacksphere_token'); queryClient.clear(); setLocation('/'); } });
  return <div className="app-frame">
    <aside className={cn('sidebar', mobileOpen && 'sidebar-open')}>
      <div className="sidebar-top"><Logo dark /><button className="sidebar-close" onClick={() => setMobileOpen(false)} data-testid="button-close-menu"><X size={18} /></button></div>
      <div className="sidebar-kicker">Workspace</div>
      <nav className="sidebar-nav">
        {nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={cn('side-link', isActive(href) && 'side-link-active')} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} /><span>{label}</span>{label === 'For you' && <span className="nav-pip" />}</Link>)}
      </nav>
      {user?.role !== 'USER' && <><div className="sidebar-kicker sidebar-kicker-spaced">Manage</div><nav className="sidebar-nav">
        {user?.role === 'ORGANIZER' && <Link href="/organizer" className={cn('side-link', isActive('/organizer') && 'side-link-active')} data-testid="link-nav-organizer"><BarChart3 size={17} /><span>Organizer studio</span></Link>}
        {user?.role === 'ADMIN' && <Link href="/admin" className={cn('side-link', isActive('/admin') && 'side-link-active')} data-testid="link-nav-admin"><ShieldCheck size={17} /><span>Admin console</span></Link>}
      </nav></>}
      <div className="sidebar-prompt"><div className="prompt-orbit"><Zap size={16} /></div><strong>Ship something real.</strong><p>Find a weekend-sized problem and a team that gets it.</p><Link href="/hackathons" className="prompt-link" data-testid="link-sidebar-discover">Explore now <ArrowRight size={14} /></Link></div>
      <div className="sidebar-bottom">
        <Link href="/profile" className="profile-mini" data-testid="link-sidebar-profile"><span className="avatar avatar-sm">{initials(user?.name)}</span><span className="min-w-0"><strong className="truncate block">{user?.name || 'Your profile'}</strong><small>{user?.role?.toLowerCase() || 'developer'}</small></span><ChevronRight size={14} className="ml-auto opacity-40" /></Link>
        <button className="side-link side-logout" onClick={doLogout} data-testid="button-logout"><LogOut size={16} /><span>Sign out</span></button>
      </div>
    </aside>
    <main className="main-shell">
      <header className="app-header"><button className="mobile-menu" onClick={() => setMobileOpen(true)} data-testid="button-open-menu"><Menu size={21} /></button><div className="header-heading">{eyebrow && <span className="eyebrow">{eyebrow}</span>}{title && <h1>{title}</h1>}</div><div className="header-actions"><button className="icon-button" data-testid="button-notifications" aria-label="Notifications"><Bell size={18} /><i /></button><Link href="/profile" className="avatar avatar-sm" data-testid="link-header-profile">{initials(user?.name)}</Link></div></header>
      <div className="page-wrap">{children}</div>
    </main>
  </div>;
}

function PublicHeader() {
  const [location] = useLocation();
  return <header className="public-header"><Logo /><nav className="public-nav"><Link href="/hackathons" className={location === '/hackathons' ? 'active' : ''} data-testid="link-public-discover">Discover</Link><Link href="/about" className={location === '/about' ? 'active' : ''} data-testid="link-public-about">Why HackSphere</Link></nav><div className="public-actions"><Link href="/login" className="header-login" data-testid="link-login">Sign in</Link><Link href="/register" className="btn btn-primary btn-small" data-testid="link-register">Create account <ArrowRight size={15} /></Link></div></header>;
}

function HackathonVisual({ tone = 'amber', compact = false }: { tone?: string; compact?: boolean }) {
  return <div className={cn('hack-visual', `tone-${tone}`, compact && 'hack-visual-compact')}><div className="visual-grid" /><div className="visual-orb orb-one" /><div className="visual-orb orb-two" /><span className="visual-code">{"</>"}</span></div>;
}

function HackathonCard({ hackathon, featured = false }: { hackathon: any; featured?: boolean }) {
  const bookmark = useBookmarkHackathon();
  const unbookmark = useUnbookmarkHackathon();
  const toggleBookmark = () => hackathon.bookmarked ? unbookmark.mutate({ id: hackathon.id }) : bookmark.mutate({ id: hackathon.id });
  return <article className={cn('hack-card', featured && 'hack-card-featured')} data-testid={`card-hackathon-${hackathon.id}`}>
    <Link href={`/hackathons/${hackathon.id}`} className="block" data-testid={`link-hackathon-${hackathon.id}`}><HackathonVisual tone={hackathon.coverTone} compact={featured} /></Link>
    <div className="hack-card-body">
      <div className="flex items-start justify-between gap-3"><div className="flex gap-2 flex-wrap"><Badge tone="yellow">{hackathon.category}</Badge><Badge>{hackathon.mode}</Badge></div><button className={cn('bookmark-button', hackathon.bookmarked && 'bookmarked')} onClick={toggleBookmark} data-testid={`button-bookmark-${hackathon.id}`} aria-label="Bookmark hackathon">{hackathon.bookmarked ? <BookmarkCheck size={17} /> : <Bookmark size={17} />}</button></div>
      <Link href={`/hackathons/${hackathon.id}`} className="hack-card-title" data-testid={`link-title-${hackathon.id}`}>{hackathon.title}</Link>
      <p className="hack-card-description">{hackathon.description}</p>
      <div className="tag-row">{hackathon.technologies?.slice(0, 3).map((tech: string) => <span className="tech-tag" key={tech}>{tech}</span>)}</div>
      <div className="hack-card-meta"><span><Clock3 size={14} /> Ends {date(hackathon.registrationDeadline)}</span><span><Trophy size={14} /> {money(hackathon.prizePool)}</span></div>
    </div>
  </article>;
}

function Landing() {
  const { data, isLoading } = useListHackathons({ sort: 'recommended', limit: 3, page: 1 });
  const featured = data?.items || [];
  return <div className="public-page"><PublicHeader /><section className="hero-section"><div className="hero-copy"><div className="hero-kicker"><span className="kicker-dot" /> The launchpad for your next build</div><h1>Ideas are easy.<br /><em>Shipping is rare.</em></h1><p className="hero-lede">HackSphere helps developers find the right hackathon, the right teammates, and a clear path from <strong>“what if?”</strong> to demo day.</p><div className="hero-actions"><Link href="/hackathons" className="btn btn-primary btn-large" data-testid="link-hero-explore">Find your next build <ArrowRight size={18} /></Link><Link href="/register" className="btn btn-ghost btn-large" data-testid="link-hero-start">Start building <span className="arrow-circle"><ArrowRight size={14} /></span></Link></div><div className="hero-proof"><div className="avatar-stack"><span className="avatar avatar-xs avatar-yellow">MC</span><span className="avatar avatar-xs avatar-teal">AS</span><span className="avatar avatar-xs avatar-coral">JR</span><span className="avatar avatar-xs avatar-ink">+2k</span></div><span>Join 2,400+ builders in motion</span></div></div><div className="hero-art" aria-label="HackSphere build flow illustration"><div className="hero-art-glow" /><div className="hero-card hero-card-main"><div className="hero-card-top"><span className="status-live"><i /> LIVE</span><span className="mono">WKND_042</span></div><div className="hero-terminal"><p><span className="terminal-purple">const</span> <span className="terminal-yellow">idea</span> = <span className="terminal-teal">"worth shipping"</span></p><p><span className="terminal-purple">await</span> <span className="terminal-yellow">build</span>(idea)</p><p className="terminal-cursor">▌</p></div><div className="hero-card-bottom"><span>Demo day in</span><strong>02d 14h 09m</strong></div></div><div className="float-note note-top"><Sparkles size={15} /><span><strong>94%</strong> match</span></div><div className="float-note note-bottom"><Users size={15} /><span>3 teammates found</span></div><div className="hero-ring ring-one" /><div className="hero-ring ring-two" /></div></section><section className="marquee-strip"><div>DISCOVER <span>•</span> TEAM UP <span>•</span> BUILD LOUD <span>•</span> SHIP IT <span>•</span> DISCOVER <span>•</span> TEAM UP <span>•</span> BUILD LOUD <span>•</span> SHIP IT</div></section><section className="landing-section intro-section"><div className="section-label">01 / The loop</div><div className="intro-grid"><h2>Less browsing.<br /><span>More building.</span></h2><div><p className="section-lede">Most hackathon platforms stop at a list. HackSphere stays with you through the parts that actually decide whether an idea ships.</p><Link href="/about" className="text-link" data-testid="link-learn-loop">See how it works <ArrowRight size={15} /></Link></div></div><div className="loop-grid"><div className="loop-step"><span className="loop-num">01</span><Search size={23} /><h3>Find the spark</h3><p>Search by the stack you want to use, the problem you care about, or simply how much time you have.</p></div><div className="loop-step loop-step-offset"><span className="loop-num">02</span><Users size={23} /><h3>Meet your people</h3><p>See what every team is missing and invite builders with complementary skills.</p></div><div className="loop-step"><span className="loop-num">03</span><Rocket size={23} /><h3>Ship with signal</h3><p>Keep your project moving with clear deadlines, a focused workspace, and no mystery recommendations.</p></div></div></section><section className="landing-section discover-section"><div className="section-heading-row"><div><div className="section-label">02 / Worth your weekend</div><h2>Open calls for<br /><span>curious minds.</span></h2></div><Link href="/hackathons" className="btn btn-outline" data-testid="link-view-all-hackathons">View all hackathons <ArrowRight size={15} /></Link></div>{isLoading ? <LoadingState /> : <div className="featured-grid">{featured.length ? featured.map((h: any, i: number) => <HackathonCard key={h.id} hackathon={h} featured={i === 0} />) : <EmptyState icon={Search} title="The next brief is loading" text="Check the discovery board for the latest calls." action={<Link href="/hackathons" className="btn btn-outline">Browse all</Link>} />}</div>}</section><section className="manifesto-section"><div className="manifesto-stamp">HS<br /><span>EST. 2024</span></div><blockquote>“The best hackathon<br />is the one you <em>finish.</em>”</blockquote><p>HackSphere is built for the messy, electric middle between a blank repo and a working demo.</p><Link href="/register" className="btn btn-yellow" data-testid="link-manifesto-join">Make something real <ArrowRight size={16} /></Link></section><footer className="public-footer"><Logo /><span>Built for the curious. © 2024 HackSphere.</span><div><Link href="/about" data-testid="link-footer-about">About</Link><Link href="/login" data-testid="link-footer-login">Sign in</Link></div></footer></div>;
}

function About() {
  return <div className="public-page"><PublicHeader /><section className="about-hero"><div className="section-label">Why HackSphere</div><h1>A better place to<br /><em>begin.</em></h1><p>Hackathons are not just competitions. They are a forcing function for the work you keep saying you will make.</p></section><section className="about-points"><div className="about-point"><span>01</span><Target size={24} /><div><h2>Useful over noisy</h2><p>Search and filters that respect your time. Every brief tells you what matters before you commit a weekend.</p></div></div><div className="about-point"><span>02</span><Lightbulb size={24} /><div><h2>Recommendations you can trust</h2><p>See why a hackathon is recommended: your skills, interests, difficulty, and the kind of team you want to join.</p></div></div><div className="about-point"><span>03</span><Code2 size={24} /><div><h2>Momentum in one place</h2><p>Registrations, teams, projects, and deadlines stay connected so your build does not disappear into tabs.</p></div></div></section><section className="about-quote"><p>We believe a good platform should get out of your way at exactly the right moment.</p><Link href="/hackathons" className="btn btn-primary" data-testid="link-about-discover">Explore the board <ArrowRight size={16} /></Link></section><footer className="public-footer"><Logo /><span>Built for the curious. © 2024 HackSphere.</span></footer></div>;
}

function Hackathons() {
  const [search, setSearch] = useState('');
  const [difficulty, setDifficulty] = useState('');
  const [mode, setMode] = useState('');
  const [sort, setSort] = useState('recommended');
  const params = useMemo(() => ({ search: search || undefined, difficulty: difficulty || undefined, mode: mode || undefined, sort, limit: 12, page: 1 }), [search, difficulty, mode, sort]);
  const query = useListHackathons(params as any);
  return <AppShell title="Discover" eyebrow="The open board"><div className="content-intro"><div><p className="page-lede">Find a brief that makes you want to open your editor.</p></div><div className="mini-stat"><span className="mono">LIVE NOW</span><strong>{query.data?.total ?? '—'}</strong><span>hackathons on the board</span></div></div><div className="discovery-toolbar"><div className="search-box"><Search size={18} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by title, problem, or stack" data-testid="input-search-hackathons" /></div><div className="filter-wrap"><Filter size={15} /><select value={difficulty} onChange={(e) => setDifficulty(e.target.value)} data-testid="select-difficulty"><option value="">Any level</option><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option></select><select value={mode} onChange={(e) => setMode(e.target.value)} data-testid="select-mode"><option value="">Any format</option><option value="online">Online</option><option value="hybrid">Hybrid</option><option value="offline">In person</option></select><select value={sort} onChange={(e) => setSort(e.target.value)} data-testid="select-sort"><option value="recommended">Recommended</option><option value="deadline">Deadline soon</option><option value="newest">Newest</option><option value="popular">Popular</option><option value="prize">Prize pool</option></select></div></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.items?.length ? <><div className="results-line"><span><strong>{query.data.total}</strong> opportunities</span><span className="mono">PAGE {query.data.page} / {query.data.pages}</span></div><div className="hack-grid">{query.data.items.map((h: any) => <HackathonCard key={h.id} hackathon={h} />)}</div></> : <EmptyState icon={Search} title="No briefs match that search" text="Try a broader stack, another difficulty, or clear a filter." action={<Button variant="outline" onClick={() => { setSearch(''); setDifficulty(''); setMode(''); }} testId="button-clear-filters">Clear filters</Button>} />}</AppShell>;
}

function HackathonDetail() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);
  const query = useGetHackathon(id, { query: { queryKey: getGetHackathonQueryKey(id) } });
  const register = useRegisterForHackathon();
  const bookmark = useBookmarkHackathon();
  const unbookmark = useUnbookmarkHackathon();
  const [notice, setNotice] = useState('');
  if (query.isLoading) return <AppShell><LoadingState /></AppShell>;
  if (query.isError || !query.data) return <AppShell><ErrorState onRetry={() => query.refetch()} /></AppShell>;
  const h: any = query.data;
  const doRegister = () => register.mutate({ id }, { onSuccess: () => { setNotice('You are on the list. Time to make a plan.'); queryClient.invalidateQueries({ queryKey: getGetHackathonQueryKey(id) }); } });
  const doBookmark = () => (h.bookmarked ? unbookmark : bookmark).mutate({ id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetHackathonQueryKey(id) }) });
  return <AppShell><div className="detail-back"><Link href="/hackathons" data-testid="link-back-discover"><ChevronRight size={15} className="rotate-180" /> Back to discover</Link></div><section className="detail-hero"><div className="detail-hero-copy"><div className="flex gap-2 flex-wrap"><Badge tone="yellow">{h.category}</Badge><Badge tone="teal">{h.difficulty}</Badge><Badge>{h.mode}</Badge></div><h1>{h.title}</h1><p>{h.description}</p><div className="organizer-line"><span className="avatar avatar-xs avatar-ink">{initials(h.organizer?.name)}</span><span>Hosted by <strong>{h.organizer?.name}</strong></span><span className="dot-divider" /> <span>{h.participants} builders joined</span></div></div><HackathonVisual tone={h.coverTone} /></section><div className="detail-layout"><div className="detail-main"><div className="detail-tabs"><a href="#brief" data-testid="link-tab-brief">The brief</a><a href="#rules" data-testid="link-tab-rules">Rules</a><a href="#faq" data-testid="link-tab-faq">FAQ</a></div><section id="brief" className="detail-section"><div className="section-label">The brief</div><h2>Build for the problem,<br /><span>not the applause.</span></h2><p>{h.problemStatement}</p></section><section id="rules" className="detail-section detail-rules"><div className="section-label">Good to know</div><div className="rules-grid"><div><strong>Eligibility</strong><p>{h.eligibility}</p></div><div><strong>Rules</strong><p>{h.rules}</p></div></div></section><section id="faq" className="detail-section"><div className="section-label">FAQ</div>{h.faqs?.map((faq: string, i: number) => <details key={faq} open={i === 0}><summary>{faq.split('?')[0]}?</summary><p>Check the organizer's latest guidance in the event workspace after registering.</p></details>)}</section></div><aside className="detail-aside"><div className="sticky-card"><div className="deadline-callout"><span><Clock3 size={15} /> Registration closes</span><strong>{dateTime(h.registrationDeadline)}</strong></div><div className="detail-stats"><div><span>Prize pool</span><strong>{money(h.prizePool)}</strong></div><div><span>Team size</span><strong>{h.teamSizeMin}–{h.teamSizeMax}</strong></div><div><span>Build starts</span><strong>{date(h.startDate)}</strong></div><div><span>Submit by</span><strong>{dateTime(h.submissionDeadline)}</strong></div></div>{notice && <div className="success-note"><Check size={15} /> {notice}</div>}<Button className="w-full justify-center" disabled={h.registered || register.isPending} onClick={doRegister} testId="button-register-hackathon">{h.registered ? <><Check size={16} /> Registered</> : register.isPending ? 'Joining…' : <>Register for this hackathon <ArrowRight size={16} /></>}</Button><Button variant="outline" className="w-full justify-center mt-2" onClick={doBookmark} testId="button-detail-bookmark">{h.bookmarked ? <><BookmarkCheck size={16} /> Saved</> : <><Bookmark size={16} /> Save for later</>}</Button></div></aside></div></AppShell>;
}

function AuthLayout({ children, title, text, mode }: { children: React.ReactNode; title: string; text: string; mode: 'login' | 'register' }) {
  return <div className="auth-page"><div className="auth-art"><Logo dark /><div className="auth-art-copy"><div className="hero-kicker"><span className="kicker-dot" /> A platform for momentum</div><h1>Make the idea<br /><em>real.</em></h1><p>Find a problem worth your weekend. Find people who make you better.</p><div className="auth-art-line"><span /><span /><span /></div></div><div className="auth-art-footer"><span>HackSphere / 2024</span><span>For builders in motion</span></div></div><div className="auth-form-side"><div className="auth-mobile-logo"><Logo /></div><div className="auth-form-wrap"><div className="section-label">{mode === 'login' ? 'Welcome back' : 'Start here'}</div><h2>{title}</h2><p className="auth-subtitle">{text}</p>{children}</div><div className="auth-bottom"><span>{mode === 'login' ? 'New to HackSphere?' : 'Already building with us?'}</span><Link href={mode === 'login' ? '/register' : '/login'} data-testid={mode === 'login' ? 'link-register-switch' : 'link-login-switch'}>{mode === 'login' ? 'Create an account' : 'Sign in'} <ArrowRight size={14} /></Link></div></div></div>;
}

function Login() {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); login.mutate({ data: { email, password } }, { onSuccess: (session) => { localStorage.setItem('hacksphere_token', session.token); queryClient.setQueryData(getGetCurrentUserQueryKey(), session.user); setLocation('/dashboard'); } }); };
  return <AuthLayout mode="login" title="Sign in to ship." text="Your next build is probably closer than you think."><form onSubmit={submit} className="auth-form"><label>Email address<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@studio.dev" required data-testid="input-email" /></label><label>Password<div className="input-with-action"><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Your password" required data-testid="input-password" /><button type="button" onClick={() => setPassword('')} data-testid="button-clear-password">Clear</button></div></label><div className="auth-options"><label className="check-label"><input type="checkbox" data-testid="input-remember" /> <span>Remember me</span></label><button type="button" className="text-button" data-testid="button-forgot-password">Forgot password?</button></div>{login.isError && <p className="form-error" data-testid="status-login-error">We could not sign you in. Check your details and try again.</p>}<Button type="submit" className="w-full justify-center" disabled={login.isPending} testId="button-submit-login">{login.isPending ? 'Signing in…' : <>Sign in <ArrowRight size={16} /></>}</Button></form></AuthLayout>;
}

function Register() {
  const [, setLocation] = useLocation();
  const register = useRegister();
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); register.mutate({ data: { name, email, password, skills: [], interests: [] } }, { onSuccess: (session) => { localStorage.setItem('hacksphere_token', session.token); queryClient.setQueryData(getGetCurrentUserQueryKey(), session.user); setLocation('/dashboard'); } }); };
  return <AuthLayout mode="register" title="Create your builder profile." text="A little context helps us point you toward the right room."><form onSubmit={submit} className="auth-form"><label>Your name<input value={name} onChange={(e) => setName(e.target.value)} placeholder="What should teammates call you?" required minLength={2} data-testid="input-name" /></label><label>Email address<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@studio.dev" required data-testid="input-register-email" /></label><label>Create a password<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="At least 8 characters" required minLength={8} data-testid="input-register-password" /></label>{register.isError && <p className="form-error" data-testid="status-register-error">That account could not be created. Try another email.</p>}<Button type="submit" className="w-full justify-center" disabled={register.isPending} testId="button-submit-register">{register.isPending ? 'Creating profile…' : <>Create account <ArrowRight size={16} /></>}</Button><p className="legal-copy">By joining, you agree to build things you can explain.</p></form></AuthLayout>;
}

function StatCard({ label, value, detail, icon: Icon, accent = 'yellow' }: { label: string; value: React.ReactNode; detail: string; icon: typeof Trophy; accent?: string }) { return <div className={cn('stat-card', `stat-${accent}`)}><div className="stat-top"><span>{label}</span><Icon size={17} /></div><strong>{value}</strong><small>{detail}</small></div>; }

function Dashboard() {
  const query = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const d: any = query.data;
  if (query.isLoading) return <AppShell title="Overview" eyebrow="Your workspace"><LoadingState /></AppShell>;
  if (query.isError) return <AppShell title="Overview" eyebrow="Your workspace"><ErrorState onRetry={() => query.refetch()} /></AppShell>;
  return <AppShell title="Overview" eyebrow="Your workspace"><div className="welcome-row"><div><p className="page-lede">A good idea needs a little structure.</p><p className="muted-copy">Here is everything moving in your orbit.</p></div><Link href="/hackathons" className="btn btn-primary" data-testid="link-dashboard-discover">Find a hackathon <ArrowRight size={16} /></Link></div><div className="stats-grid"><StatCard label="Registered" value={d?.registeredHackathons ?? 0} detail="hackathons in your orbit" icon={CalendarDays} /><StatCard label="Active teams" value={d?.activeTeams ?? 0} detail="people building with you" icon={Users} accent="teal" /><StatCard label="Projects shipped" value={d?.projectsSubmitted ?? 0} detail="submitted to the board" icon={Rocket} accent="coral" /><StatCard label="Certificates" value={d?.certificates ?? 0} detail="earned by showing up" icon={Trophy} accent="ink" /></div><div className="dashboard-grid"><section className="panel upcoming-panel"><div className="panel-heading"><div><div className="section-label">On deck</div><h2>Upcoming</h2></div><Link href="/registrations" className="text-link" data-testid="link-dashboard-registrations">View registrations <ArrowRight size={14} /></Link></div>{d?.upcoming?.length ? d.upcoming.slice(0, 3).map((h: any) => <Link href={`/hackathons/${h.id}`} className="upcoming-item" key={h.id} data-testid={`link-upcoming-${h.id}`}><HackathonVisual tone={h.coverTone} compact /><div><Badge tone="yellow">{h.category}</Badge><h3>{h.title}</h3><p><Clock3 size={13} /> Registration closes {date(h.registrationDeadline)}</p></div><ChevronRight size={17} /></Link>) : <EmptyState icon={CalendarDays} title="Your calendar is open" text="Register for a hackathon and your next deadline will show up here." action={<Link href="/hackathons" className="btn btn-outline">Find a brief</Link>} />}</section><section className="panel activity-panel"><div className="panel-heading"><div><div className="section-label">Signal</div><h2>Recent activity</h2></div><Bell size={18} className="muted-icon" /></div>{d?.activity?.length ? <div className="activity-list">{d.activity.slice(0, 6).map((item: string, i: number) => <div className="activity-item" key={`${item}-${i}`} data-testid={`text-activity-${i}`}><span className={cn('activity-dot', i === 0 && 'activity-dot-live')} /><p>{item}</p><span className="activity-time">{i + 1}h</span></div>)}</div> : <EmptyState icon={Bell} title="No new signal" text="Updates from your teams will appear here." />}</section></div><section className="panel rec-panel"><div className="panel-heading"><div><div className="section-label">Picked for your stack</div><h2>Worth a closer look</h2></div><Link href="/recommendations" className="text-link" data-testid="link-dashboard-recommendations">See all recommendations <ArrowRight size={14} /></Link></div><div className="rec-strip">{d?.recommendations?.slice(0, 3).map((h: any) => <Link href={`/hackathons/${h.id}`} className="rec-item" key={h.id} data-testid={`link-dashboard-rec-${h.id}`}><div className="rec-score"><span>{Math.round(h.score)}%</span><small>match</small></div><div className="min-w-0"><h3 className="truncate">{h.title}</h3><p>{h.reasons?.[0] || `${h.category} · ${h.difficulty}`}</p></div><ArrowRight size={16} /></Link>)}</div></section></AppShell>;
}

function Registrations() {
  const query = useGetMyRegistrations({ query: { queryKey: getGetMyRegistrationsQueryKey() } });
  const cancel = useCancelRegistration();
  return <AppShell title="Registrations" eyebrow="Your commitments"><div className="content-intro"><p className="page-lede">The weekends you said yes to.</p><Link href="/hackathons" className="btn btn-primary" data-testid="link-registrations-discover">Add a new one <Plus size={16} /></Link></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="registration-list">{query.data.map((r: any) => <div className="registration-row" key={r.id} data-testid={`row-registration-${r.id}`}><HackathonVisual tone={r.hackathon.coverTone} compact /><div className="registration-main"><div className="flex items-center gap-2"><Badge tone={r.status === 'REGISTERED' ? 'teal' : 'neutral'}>{r.status.toLowerCase()}</Badge><span className="mono muted-label">JOINED {date(r.createdAt)}</span></div><Link href={`/hackathons/${r.hackathon.id}`} className="registration-title" data-testid={`link-registration-${r.id}`}>{r.hackathon.title}</Link><p>{r.hackathon.category} · {r.hackathon.mode} · closes {date(r.hackathon.registrationDeadline)}</p></div><div className="registration-actions"><Link href={`/hackathons/${r.hackathon.id}`} className="icon-button" data-testid={`button-open-registration-${r.id}`}><ExternalLink size={16} /></Link>{r.status === 'REGISTERED' && <Button variant="ghost" onClick={() => cancel.mutate({ id: r.id }, { onSuccess: () => query.refetch() })} testId={`button-cancel-registration-${r.id}`}>Cancel</Button>}</div></div>)}</div> : <EmptyState icon={CalendarDays} title="No commitments yet" text="The right brief has a way of making the calendar feel exciting." action={<Link href="/hackathons" className="btn btn-primary">Browse hackathons</Link>} />}</AppShell>;
}

function Teams() {
  const query = useGetMyTeams({ query: { queryKey: getGetMyTeamsQueryKey() } });
  const create = useCreateTeam(); const invite = useInviteToTeam();
  const [showCreate, setShowCreate] = useState(false); const [teamName, setTeamName] = useState(''); const [description, setDescription] = useState(''); const [inviteEmail, setInviteEmail] = useState(''); const [selected, setSelected] = useState<number | null>(null);
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { name: teamName, description } }, { onSuccess: () => { setShowCreate(false); setTeamName(''); setDescription(''); query.refetch(); } }); };
  return <AppShell title="Teams" eyebrow="Build together"><div className="content-intro"><p className="page-lede">Good work gets better in a room.</p><Button onClick={() => setShowCreate(true)} testId="button-create-team"><Plus size={16} /> Create a team</Button></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="team-grid">{query.data.map((team: any) => <article className="team-card" key={team.id} data-testid={`card-team-${team.id}`}><div className="team-card-top"><div className="team-glyph"><Users size={20} /></div><Badge tone={team.memberCount >= team.maxMembers ? 'neutral' : 'yellow'}>{team.memberCount}/{team.maxMembers} spots</Badge></div><h2>{team.name}</h2><p>{team.description}</p>{team.hackathonTitle && <span className="team-event"><Rocket size={13} /> {team.hackathonTitle}</span>}<div className="member-stack">{team.members?.map((m: any) => <span title={m.name} className="avatar avatar-xs avatar-random" key={m.id}>{initials(m.name)}</span>)}<span className="member-count">{team.memberCount} builders</span></div><div className="team-card-actions"><Button variant="outline" onClick={() => setSelected(selected === team.id ? null : team.id)} testId={`button-invite-toggle-${team.id}`}><Plus size={15} /> Invite</Button>{selected === team.id && <form className="inline-invite" onSubmit={(e) => { e.preventDefault(); invite.mutate({ id: team.id, data: { email: inviteEmail } }, { onSuccess: () => setInviteEmail('') }); }}><input type="email" placeholder="builder@email.com" value={inviteEmail} onChange={(e) => setInviteEmail(e.target.value)} required data-testid={`input-invite-${team.id}`} /><Button type="submit" disabled={invite.isPending} testId={`button-send-invite-${team.id}`}>Send</Button></form>}</div></article>)}</div> : <EmptyState icon={Users} title="Your team room is waiting" text="Start a team for a hackathon, then invite people who fill the gaps." action={<Button onClick={() => setShowCreate(true)} testId="button-empty-create-team">Create your first team</Button>} />}{showCreate && <div className="modal-backdrop"><div className="modal-card"><div className="modal-heading"><div><div className="section-label">New crew</div><h2>Create a team</h2></div><button className="icon-button" onClick={() => setShowCreate(false)} data-testid="button-close-team-modal"><X size={18} /></button></div><form onSubmit={submit} className="stack-form"><label>Team name<input value={teamName} onChange={(e) => setTeamName(e.target.value)} placeholder="Something people want to join" required data-testid="input-team-name" /></label><label>What are you building?<textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="A sentence or two about the idea" required data-testid="input-team-description" /></label><div className="modal-actions"><Button variant="ghost" onClick={() => setShowCreate(false)} testId="button-cancel-team">Cancel</Button><Button type="submit" disabled={create.isPending} testId="button-submit-team">{create.isPending ? 'Creating…' : 'Create team'}</Button></div></form></div></div>}</AppShell>;
}

function Projects() {
  const query = useGetMyProjects({ query: { queryKey: getGetMyProjectsQueryKey() } });
  const create = useCreateProject(); const submit = useSubmitProject();
  const [showCreate, setShowCreate] = useState(false); const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [githubUrl, setGithubUrl] = useState('');
  const addProject = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { name, description, githubUrl, technologies: [] } }, { onSuccess: () => { setShowCreate(false); query.refetch(); setName(''); setDescription(''); setGithubUrl(''); } }); };
  return <AppShell title="Projects" eyebrow="Your builds"><div className="content-intro"><p className="page-lede">A blank repo is still a beginning.</p><Button onClick={() => setShowCreate(true)} testId="button-create-project"><Plus size={16} /> New project</Button></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="project-list">{query.data.map((p: any) => <article className="project-row" key={p.id} data-testid={`row-project-${p.id}`}><div className="project-icon"><FileCode2 size={21} /></div><div className="project-main"><div className="flex items-center gap-2"><Badge tone={p.status === 'SUBMITTED' ? 'teal' : 'yellow'}>{p.status.replace('_', ' ').toLowerCase()}</Badge>{p.hackathonTitle && <span className="mono muted-label">{p.hackathonTitle}</span>}</div><h2>{p.name}</h2><p>{p.description}</p><div className="tag-row">{p.technologies?.map((t: string) => <span className="tech-tag" key={t}>{t}</span>)}</div></div><div className="project-actions">{p.githubUrl && <a className="icon-button" href={p.githubUrl} target="_blank" rel="noreferrer" data-testid={`link-project-github-${p.id}`}><Github size={16} /></a>}{p.status === 'DRAFT' && <Button onClick={() => submit.mutate({ id: p.id }, { onSuccess: () => query.refetch() })} disabled={submit.isPending} testId={`button-submit-project-${p.id}`}><Rocket size={15} /> Submit</Button>}</div></article>)}</div> : <EmptyState icon={FileCode2} title="No projects yet" text="Capture the idea before it gets away. You can refine it with your team later." action={<Button onClick={() => setShowCreate(true)} testId="button-empty-create-project">Start a project</Button>} />}{showCreate && <div className="modal-backdrop"><div className="modal-card"><div className="modal-heading"><div><div className="section-label">New build</div><h2>Start a project</h2></div><button className="icon-button" onClick={() => setShowCreate(false)} data-testid="button-close-project-modal"><X size={18} /></button></div><form onSubmit={addProject} className="stack-form"><label>Project name<input value={name} onChange={(e) => setName(e.target.value)} required placeholder="A name you can say out loud" data-testid="input-project-name" /></label><label>What is it?<textarea value={description} onChange={(e) => setDescription(e.target.value)} required placeholder="What will this make possible?" data-testid="input-project-description" /></label><label>GitHub URL<input value={githubUrl} onChange={(e) => setGithubUrl(e.target.value)} required type="url" placeholder="https://github.com/you/project" data-testid="input-project-github" /></label><div className="modal-actions"><Button variant="ghost" onClick={() => setShowCreate(false)} testId="button-cancel-project">Cancel</Button><Button type="submit" disabled={create.isPending} testId="button-submit-project">{create.isPending ? 'Creating…' : 'Create draft'}</Button></div></form></div></div>}</AppShell>;
}

function Profile() {
  const query = useGetProfile({ query: { queryKey: getGetProfileQueryKey() } });
  const update = useUpdateProfile();
  const [form, setForm] = useState<any>({ name: '', bio: '', skills: '', interests: '', githubUrl: '', linkedinUrl: '', portfolioUrl: '' });
  const [ready, setReady] = useState(false);
  if (query.data && !ready) { const p: any = query.data; setForm({ name: p.name || '', bio: p.bio || '', skills: p.skills?.join(', ') || '', interests: p.interests?.join(', ') || '', githubUrl: p.githubUrl || '', linkedinUrl: p.linkedinUrl || '', portfolioUrl: p.portfolioUrl || '' }); setReady(true); }
  if (query.isLoading) return <AppShell title="Profile" eyebrow="Your signal"><LoadingState /></AppShell>;
  if (query.isError) return <AppShell title="Profile" eyebrow="Your signal"><ErrorState onRetry={() => query.refetch()} /></AppShell>;
  const save = (e: React.FormEvent) => { e.preventDefault(); update.mutate({ data: { ...form, skills: form.skills.split(',').map((x: string) => x.trim()).filter(Boolean), interests: form.interests.split(',').map((x: string) => x.trim()).filter(Boolean) } }); };
  return <AppShell title="Profile" eyebrow="Your signal"><div className="profile-layout"><section className="panel profile-form-panel"><div className="profile-heading"><span className="avatar avatar-lg">{initials(form.name)}</span><div><div className="section-label">Builder profile</div><h2>{form.name || 'Your profile'}</h2><p>Help the right team recognize you.</p></div></div><form onSubmit={save} className="stack-form"><div className="form-two-col"><label>Name<input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required data-testid="input-profile-name" /></label><label>Email<input value={(query.data as any)?.email || ''} disabled data-testid="input-profile-email" /></label></div><label>Bio<textarea value={form.bio} onChange={(e) => setForm({ ...form, bio: e.target.value })} placeholder="What do you like making?" data-testid="input-profile-bio" /></label><label>Skills <span className="field-hint">separate with commas</span><input value={form.skills} onChange={(e) => setForm({ ...form, skills: e.target.value })} placeholder="React, Python, product design" data-testid="input-profile-skills" /></label><label>Interests <span className="field-hint">separate with commas</span><input value={form.interests} onChange={(e) => setForm({ ...form, interests: e.target.value })} placeholder="Climate, accessibility, music" data-testid="input-profile-interests" /></label><div className="form-divider"><span>Links</span></div><div className="form-two-col"><label>GitHub<input value={form.githubUrl} onChange={(e) => setForm({ ...form, githubUrl: e.target.value })} placeholder="github.com/you" data-testid="input-profile-github" /></label><label>Portfolio<input value={form.portfolioUrl} onChange={(e) => setForm({ ...form, portfolioUrl: e.target.value })} placeholder="you.dev" data-testid="input-profile-portfolio" /></label></div><div className="form-actions"><span className="save-status">{update.isSuccess ? <><Check size={14} /> Saved</> : 'Changes stay private until you share them.'}</span><Button type="submit" disabled={update.isPending} testId="button-save-profile">{update.isPending ? 'Saving…' : 'Save profile'}</Button></div></form></section><aside className="profile-aside"><div className="completion-card"><div className="section-label">Profile strength</div><div className="completion-value">{(query.data as any)?.profileCompletion || 0}<span>%</span></div><div className="progress-track"><div style={{ width: `${(query.data as any)?.profileCompletion || 0}%` }} /></div><p>A complete profile helps your recommendations get sharper.</p></div><div className="panel profile-note"><Sparkles size={19} /><h3>Small signal, big difference</h3><p>Tell people what you want to learn, not just what you already know.</p></div></aside></div></AppShell>;
}

function Recommendations() {
  const query = useGetRecommendations({ query: { queryKey: getGetRecommendationsQueryKey() } });
  return <AppShell title="For you" eyebrow="Recommendations"><div className="recommendation-hero"><div><div className="section-label">A better shortlist</div><p className="page-lede">Hackathons that fit the way you build.</p><p className="muted-copy">Every match comes with a reason, so you can decide for yourself.</p></div><div className="match-mark"><Sparkles size={19} /><span>PERSONAL<br />SIGNAL</span></div></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="recommendation-list">{query.data.map((h: any, i: number) => <article className="recommendation-row" key={h.id} data-testid={`card-recommendation-${h.id}`}><div className="match-score"><strong>{Math.round(h.score)}%</strong><span>match</span></div><div className="recommendation-body"><div className="flex gap-2"><Badge tone="yellow">{h.category}</Badge><Badge>{h.difficulty}</Badge></div><Link href={`/hackathons/${h.id}`} className="recommendation-title" data-testid={`link-recommendation-${h.id}`}>{h.title}</Link><p>{h.description}</p><div className="reason-row"><span><Sparkles size={14} /> Why this is here</span>{h.reasons?.slice(0, 2).map((reason: string) => <span className="reason-pill" key={reason}>{reason}</span>)}</div></div><Link href={`/hackathons/${h.id}`} className="icon-button" data-testid={`button-open-recommendation-${h.id}`}><ArrowRight size={16} /></Link></article>)}</div> : <EmptyState icon={Sparkles} title="Your signal is still warming up" text="Add skills and interests to your profile to unlock sharper matches." action={<Link href="/profile" className="btn btn-primary">Tune your profile</Link>} />}</AppShell>;
}

function Organizer() {
  const query = useGetOrganizerDashboard({ query: { queryKey: getGetOrganizerDashboardQueryKey() } });
  const d: any = query.data;
  return <AppShell title="Organizer studio" eyebrow="Run better events"><div className="content-intro"><p className="page-lede">The room behind the room.</p><Link href="/organizer/hackathons/new" className="btn btn-primary" data-testid="link-create-hackathon"><Plus size={16} /> Create hackathon</Link></div>{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <><div className="stats-grid organizer-stats"><StatCard label="Hackathons" value={d?.totalHackathons ?? 0} detail="events you have hosted" icon={Rocket} /><StatCard label="Registrations" value={d?.totalRegistrations ?? 0} detail="builders in your funnel" icon={Users} accent="teal" /><StatCard label="Teams formed" value={d?.totalTeams ?? 0} detail="collaborations underway" icon={Heart} accent="coral" /><StatCard label="Projects" value={d?.projectsSubmitted ?? 0} detail="submissions to review" icon={FileCode2} accent="ink" /></div><div className="analytics-grid"><section className="panel chart-panel"><div className="panel-heading"><div><div className="section-label">Momentum</div><h2>Registration trend</h2></div><Badge tone="teal">Last 8 weeks</Badge></div><div className="bar-chart">{(d?.registrationTrend || [22, 34, 29, 48, 41, 58, 51, 72]).map((n: number, i: number) => <div className="bar-column" key={i}><span style={{ height: `${Math.max(12, n)}%` }} /><small>W{i + 1}</small></div>)}</div></section><section className="panel tech-panel"><div className="panel-heading"><div><div className="section-label">Builder signal</div><h2>Popular technology</h2></div><ListFilter size={17} className="muted-icon" /></div>{(d?.technologyDistribution || []).slice(0, 5).map((t: any) => <div className="tech-bar" key={t.name}><div><span>{t.name}</span><strong>{t.count}</strong></div><div className="progress-track"><i style={{ width: `${Math.min(100, t.count * 8)}%` }} /></div></div>)}</section></div></>}</AppShell>;
}

const emptyHackathonForm: any = { title: '', description: '', problemStatement: '', category: 'Developer tools', technologies: '', mode: 'online', location: '', difficulty: 'beginner', registrationStart: '', registrationDeadline: '', startDate: '', submissionDeadline: '', prizePool: 0, teamSizeMin: 1, teamSizeMax: 4, eligibility: '', rules: '', faqs: '' };
function OrganizerHackathonForm({ edit = false }: { edit?: boolean }) {
  const params = useParams<{ id: string }>(); const id = Number(params.id);
  const existing = useGetHackathon(edit ? id : 0, { query: { enabled: edit, queryKey: getGetHackathonQueryKey(id) } });
  const create = useCreateHackathon(); const update = useUpdateHackathon(); const [, setLocation] = useLocation();
  const [form, setForm] = useState<any>(emptyHackathonForm); const [hydrated, setHydrated] = useState(false);
  if (edit && existing.data && !hydrated) { const h: any = existing.data; setForm({ ...h, technologies: h.technologies?.join(', ') || '', faqs: h.faqs?.join('\n') || '', registrationStart: h.registrationStart?.slice(0, 16), registrationDeadline: h.registrationDeadline?.slice(0, 16), startDate: h.startDate?.slice(0, 16), submissionDeadline: h.submissionDeadline?.slice(0, 16) }); setHydrated(true); }
  const set = (key: string, value: any) => setForm((current: any) => ({ ...current, [key]: value }));
  const submit = (e: React.FormEvent) => { e.preventDefault(); const data = { ...form, technologies: form.technologies.split(',').map((x: string) => x.trim()).filter(Boolean), faqs: form.faqs.split('\n').filter(Boolean), prizePool: Number(form.prizePool), teamSizeMin: Number(form.teamSizeMin), teamSizeMax: Number(form.teamSizeMax) }; if (edit) update.mutate({ id, data }, { onSuccess: () => setLocation(`/hackathons/${id}`) }); else create.mutate({ data }, { onSuccess: (result: any) => setLocation(`/hackathons/${result.id}`) }); };
  return <AppShell title={edit ? 'Edit hackathon' : 'Create hackathon'} eyebrow="Organizer studio"><div className="form-page-intro"><Link href="/organizer" className="detail-back" data-testid="link-back-organizer"><ChevronRight size={15} className="rotate-180" /> Back to studio</Link><p className="page-lede">{edit ? 'Tighten the brief. Keep the energy.' : 'Give builders a problem worth opening a repo for.'}</p></div><form onSubmit={submit} className="hackathon-editor"><section className="panel editor-section"><div className="editor-heading"><span>01</span><div><h2>The hook</h2><p>Make the first sentence impossible to ignore.</p></div></div><div className="stack-form"><label>Title<input value={form.title} onChange={(e) => set('title', e.target.value)} required minLength={3} placeholder="A name with some voltage" data-testid="input-hackathon-title" /></label><label>Short description<textarea value={form.description} onChange={(e) => set('description', e.target.value)} required minLength={20} placeholder="What will builders make, and why now?" data-testid="input-hackathon-description" /></label><label>Problem statement<textarea value={form.problemStatement} onChange={(e) => set('problemStatement', e.target.value)} required minLength={20} placeholder="The challenge in plain language" data-testid="input-hackathon-problem" /></label></div></section><section className="panel editor-section"><div className="editor-heading"><span>02</span><div><h2>The shape</h2><p>Give builders enough edges to make a good decision.</p></div></div><div className="form-two-col stack-form"><label>Category<input value={form.category} onChange={(e) => set('category', e.target.value)} required data-testid="input-hackathon-category" /></label><label>Technologies <span className="field-hint">comma separated</span><input value={form.technologies} onChange={(e) => set('technologies', e.target.value)} data-testid="input-hackathon-technologies" /></label><label>Format<select value={form.mode} onChange={(e) => set('mode', e.target.value)} data-testid="select-hackathon-mode"><option value="online">Online</option><option value="hybrid">Hybrid</option><option value="offline">In person</option></select></label><label>Difficulty<select value={form.difficulty} onChange={(e) => set('difficulty', e.target.value)} data-testid="select-hackathon-difficulty"><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option></select></label><label>Team minimum<input type="number" min="1" value={form.teamSizeMin} onChange={(e) => set('teamSizeMin', e.target.value)} data-testid="input-team-min" /></label><label>Team maximum<input type="number" min="1" value={form.teamSizeMax} onChange={(e) => set('teamSizeMax', e.target.value)} data-testid="input-team-max" /></label></div></section><section className="panel editor-section"><div className="editor-heading"><span>03</span><div><h2>The clock</h2><p>Dates create the useful kind of pressure.</p></div></div><div className="form-two-col stack-form"><label>Registration opens<input type="datetime-local" value={form.registrationStart} onChange={(e) => set('registrationStart', e.target.value)} required data-testid="input-registration-start" /></label><label>Registration closes<input type="datetime-local" value={form.registrationDeadline} onChange={(e) => set('registrationDeadline', e.target.value)} required data-testid="input-registration-deadline" /></label><label>Build starts<input type="datetime-local" value={form.startDate} onChange={(e) => set('startDate', e.target.value)} required data-testid="input-start-date" /></label><label>Submission deadline<input type="datetime-local" value={form.submissionDeadline} onChange={(e) => set('submissionDeadline', e.target.value)} required data-testid="input-submission-deadline" /></label><label>Prize pool (USD)<input type="number" min="0" value={form.prizePool} onChange={(e) => set('prizePool', e.target.value)} data-testid="input-prize-pool" /></label></div></section><section className="panel editor-section"><div className="editor-heading"><span>04</span><div><h2>The fine print</h2><p>Clear rules are a kindness.</p></div></div><div className="stack-form"><label>Eligibility<textarea value={form.eligibility} onChange={(e) => set('eligibility', e.target.value)} required data-testid="input-eligibility" /></label><label>Rules<textarea value={form.rules} onChange={(e) => set('rules', e.target.value)} required data-testid="input-rules" /></label><label>FAQs <span className="field-hint">one question per line</span><textarea value={form.faqs} onChange={(e) => set('faqs', e.target.value)} data-testid="input-faqs" /></label></div></section><div className="form-actions editor-actions"><Link href="/organizer" className="btn btn-ghost" data-testid="link-cancel-hackathon">Cancel</Link><Button type="submit" disabled={create.isPending || update.isPending} testId="button-save-hackathon">{create.isPending || update.isPending ? 'Saving…' : edit ? 'Save changes' : 'Publish hackathon'} <ArrowRight size={16} /></Button></div></form></AppShell>;
}

function Admin() {
  const analytics = useGetAdminAnalytics({ query: { queryKey: getGetAdminAnalyticsQueryKey() } });
  const users = useGetAdminUsers({ query: { queryKey: getGetAdminUsersQueryKey() } });
  const hackathons = useGetAdminHackathons({ query: { queryKey: getGetAdminHackathonsQueryKey() } });
  const d: any = analytics.data;
  return <AppShell title="Admin console" eyebrow="Keep the board healthy"><div className="content-intro"><p className="page-lede">The numbers behind the momentum.</p><Badge tone="teal"><i className="status-dot" /> Systems nominal</Badge></div>{analytics.isLoading ? <LoadingState /> : analytics.isError ? <ErrorState onRetry={() => analytics.refetch()} /> : <><div className="stats-grid admin-stats"><StatCard label="Users" value={d?.totalUsers ?? 0} detail="builders in the network" icon={Users} /><StatCard label="Organizers" value={d?.totalOrganizers ?? 0} detail="running events" icon={ShieldCheck} accent="teal" /><StatCard label="Hackathons" value={d?.totalHackathons ?? 0} detail={`${d?.activeHackathons ?? 0} active now`} icon={Rocket} accent="yellow" /><StatCard label="Projects" value={d?.totalProjects ?? 0} detail="submitted builds" icon={FileCode2} accent="coral" /></div><div className="admin-grid"><section className="panel table-panel"><div className="panel-heading"><div><div className="section-label">People</div><h2>Recent users</h2></div><button className="icon-button" data-testid="button-filter-users"><Filter size={16} /></button></div>{users.isLoading ? <Skeleton className="h-32 w-full" /> : <div className="data-table"><div className="table-row table-head"><span>User</span><span>Role</span><span>Profile</span></div>{(users.data as any[] || []).slice(0, 5).map((u: any) => <div className="table-row" key={u.id} data-testid={`row-admin-user-${u.id}`}><span className="user-cell"><span className="avatar avatar-xs">{initials(u.name)}</span>{u.name}</span><Badge tone={u.role === 'ORGANIZER' ? 'yellow' : 'neutral'}>{u.role.toLowerCase()}</Badge><span className="mono">{u.profileCompletion}%</span></div>)}</div>}</section><section className="panel table-panel"><div className="panel-heading"><div><div className="section-label">Content</div><h2>Hackathons</h2></div><button className="icon-button" data-testid="button-filter-hackathons"><ListFilter size={16} /></button></div>{hackathons.isLoading ? <Skeleton className="h-32 w-full" /> : <div className="data-table"><div className="table-row table-head"><span>Hackathon</span><span>Organizer</span><span>State</span></div>{(hackathons.data as any[] || []).slice(0, 5).map((h: any) => <div className="table-row" key={h.id} data-testid={`row-admin-hackathon-${h.id}`}><span className="truncate">{h.title}</span><span>{h.organizer?.name || '—'}</span><Badge tone="teal">active</Badge></div>)}</div>}</section></div></>}</AppShell>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch>
    <Route path="/" component={Landing} /><Route path="/about" component={About} /><Route path="/login" component={Login} /><Route path="/register" component={Register} />
    <Route path="/hackathons" component={Hackathons} /><Route path="/hackathons/:id" component={HackathonDetail} />
    <Route path="/dashboard" component={Dashboard} /><Route path="/registrations" component={Registrations} /><Route path="/teams" component={Teams} /><Route path="/projects" component={Projects} /><Route path="/profile" component={Profile} /><Route path="/recommendations" component={Recommendations} />
    <Route path="/organizer/hackathons/new" component={() => <OrganizerHackathonForm />} /><Route path="/organizer/hackathons/:id/edit" component={() => <OrganizerHackathonForm edit />} /><Route path="/organizer" component={Organizer} /><Route path="/admin" component={Admin} />
    <Route component={NotFound} />
  </Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;
